1	"use client";
2	
3	import { useEffect, useMemo, useRef, useState } from "react";
4	import { createPortal } from "react-dom";
5	import type { Terminal as XTerm } from "@xterm/xterm";
6	import type { FitAddon as XFitAddon } from "@xterm/addon-fit";
7	import "@xterm/xterm/css/xterm.css";
8	
9	/**
10	 * In-portal web terminal — a slide-in panel with an xterm.js terminal wired to
11	 * a real root shell on one of the customer's running servers.
12	 *
13	 * Security: the websocket is authorized by a short-lived token minted by
14	 * POST /api/terminal/token (which checks the session + ownership). This
15	 * component never sees any server credential — only the opaque token.
16	 *
17	 * Wire protocol (matches terminal-server/index.ts):
18	 *   client → server : JSON  {type:"data",data} | {type:"resize",cols,rows}
19	 *   server → client : raw shell output (text or binary) → written to xterm
20	 */
21	
22	export type TerminalServer = { id: string; hostname: string };
23	
24	type Status = "idle" | "connecting" | "connected" | "closed" | "error";
25	
26	export function WebTerminal({
27	  servers,
28	  onClose,
29	}: {
30	  servers: TerminalServer[];
31	  onClose: () => void;
32	}) {
33	  const [mounted, setMounted] = useState(false);
34	  const [serverId, setServerId] = useState(servers[0]?.id ?? "");
35	  const [status, setStatus] = useState<Status>("idle");
36	  const [error, setError] = useState<string | null>(null);
37	
38	  const hostRef = useRef<HTMLDivElement | null>(null);
39	  const termRef = useRef<XTerm | null>(null);
40	  const fitRef = useRef<XFitAddon | null>(null);
41	  const wsRef = useRef<WebSocket | null>(null);
42	  const roRef = useRef<ResizeObserver | null>(null);
43	  const disposedRef = useRef(false);
44	
45	  useEffect(() => {
46	    setMounted(true);
47	    return () => {
48	      disposedRef.current = true;
49	    };
50	  }, []);
51	
52	  const selected = useMemo(
53	    () => servers.find((s) => s.id === serverId) ?? null,
54	    [servers, serverId]
55	  );
56	
57	  /** Tear down the live websocket + terminal (idempotent). */
58	  function teardown() {
59	    try {
60	      roRef.current?.disconnect();
61	    } catch {
62	      /* ignore */
63	    }
64	    roRef.current = null;
65	    try {
66	      wsRef.current?.close();
67	    } catch {
68	      /* ignore */
69	    }
70	    wsRef.current = null;
71	    try {
72	      termRef.current?.dispose();
73	    } catch {
74	      /* ignore */
75	    }
76	    termRef.current = null;
77	    fitRef.current = null;
78	  }
79	
80	  useEffect(() => {
81	    // Clean up whenever the panel unmounts.
82	    return () => teardown();
83	    // eslint-disable-next-line react-hooks/exhaustive-deps
84	  }, []);
85	
86	  function sendResize() {
87	    const term = termRef.current;
88	    const fit = fitRef.current;
89	    const ws = wsRef.current;
90	    if (!term || !fit) return;
91	    try {
92	      fit.fit();
93	    } catch {
94	      /* ignore */
95	    }
96	    if (ws && ws.readyState === WebSocket.OPEN) {
97	      ws.send(JSON.stringify({ type: "resize", cols: term.cols, rows: term.rows }));
98	    }
99	  }
100	
101	  async function connect() {
102	    if (!serverId) return;
103	    setError(null);
104	    setStatus("connecting");
105	    teardown();
106	
107	    // 1. Mint a short-lived token (session + ownership checked server-side).
108	    let token: string;
109	    try {
110	      const res = await fetch("/api/terminal/token", {
111	        method: "POST",
112	        headers: { "Content-Type": "application/json" },
113	        body: JSON.stringify({ serverId }),
114	      });
115	      const body = await res.json().catch(() => ({}));
116	      if (!res.ok) throw new Error(body?.error || "Could not authorize the terminal.");
117	      token = body.token;
118	      if (!token) throw new Error("No terminal token was issued.");
119	    } catch (e) {
120	      setStatus("error");
121	      setError(e instanceof Error ? e.message : "Could not authorize the terminal.");
122	      return;
123	    }
124	    if (disposedRef.current) return;
125	
126	    // 2. Build the terminal.
127	    const [{ Terminal }, { FitAddon }] = await Promise.all([
128	      import("@xterm/xterm"),
129	      import("@xterm/addon-fit"),
130	    ]);
131	    if (disposedRef.current || !hostRef.current) return;
132	
133	    const term = new Terminal({
134	      cursorBlink: true,
135	      fontFamily:
136	        'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace',
137	      fontSize: 13,
138	      theme: { background: "#0a0e1a", foreground: "#e2e8f0", cursor: "#e2e8f0" },
139	    });
140	    const fit = new FitAddon();
141	    term.loadAddon(fit);
142	    term.open(hostRef.current);
143	    try {
144	      fit.fit();
145	    } catch {
146	      /* ignore */
147	    }
148	    termRef.current = term;
149	    fitRef.current = fit;
150	
151	    // 3. Open the websocket to the PTY backend (nginx proxies /terminal-ws).
152	    const scheme = location.protocol === "https:" ? "wss" : "ws";
153	    const ws = new WebSocket(
154	      `${scheme}://${location.host}/terminal-ws?token=${encodeURIComponent(token)}`
155	    );
156	    ws.binaryType = "arraybuffer";
157	    wsRef.current = ws;
158	
159	    ws.onopen = () => {
160	      setStatus("connected");
161	      term.focus();
162	      sendResize();
163	    };
164	    ws.onmessage = (ev) => {
165	      if (typeof ev.data === "string") {
166	        term.write(ev.data);
167	      } else if (ev.data instanceof ArrayBuffer) {
168	        term.write(new Uint8Array(ev.data));
169	      }
170	    };
171	    ws.onerror = () => {
172	      setError("Connection error.");
173	    };
174	    ws.onclose = (ev) => {
175	      setStatus((s) => (s === "error" ? s : "closed"));
176	      if (ev.reason && termRef.current) {
177	        term.write(`\r\n\x1b[90m[${ev.reason}]\x1b[0m\r\n`);
178	      }
179	    };
180	
181	    // 4. Keystrokes → server.
182	    term.onData((data) => {
183	      if (ws.readyState === WebSocket.OPEN) {
184	        ws.send(JSON.stringify({ type: "data", data }));
185	      }
186	    });
187	
188	    // 5. Keep the PTY window sized to the panel.
189	    const ro = new ResizeObserver(() => sendResize());
190	    if (hostRef.current) ro.observe(hostRef.current);
191	    roRef.current = ro;
192	  }
193	
194	  function disconnect() {
195	    teardown();
196	    setStatus("closed");
197	  }
198	
199	  const statusLabel: Record<Status, string> = {
200	    idle: "Not connected",
201	    connecting: "Connecting…",
202	    connected: "Connected",
203	    closed: "Disconnected",
204	    error: "Error",
205	  };
206	  const statusColor: Record<Status, string> = {
207	    idle: "bg-slate-500",
208	    connecting: "bg-amber-400 animate-pulse",
209	    connected: "bg-emerald-400",
210	    closed: "bg-slate-500",
211	    error: "bg-red-500",
212	  };
213	  const live = status === "connected" || status === "connecting";
214	
215	  if (!mounted) return null;
216	
217	  return createPortal(
218	    <div className="fixed inset-0 z-[70] flex justify-end" role="dialog" aria-modal="true">
219	      {/* Backdrop */}
220	      <div
221	        className="absolute inset-0 bg-black/60 backdrop-blur-sm"
222	        onClick={onClose}
223	        aria-hidden
224	      />
225	
226	      {/* Slide-in panel */}
227	      <div className="relative flex h-full w-full max-w-3xl flex-col border-l border-white/10 bg-navy-900 shadow-2xl md:w-1/2">
228	        {/* Header */}
229	        <div className="flex flex-none items-center gap-3 border-b border-white/[0.06] px-4 py-3">
230	          <div className="flex items-center gap-2">
231	            <span className={`h-2.5 w-2.5 rounded-full ${statusColor[status]}`} />
232	            <span className="text-sm font-semibold text-white">Terminal</span>
233	            <span className="text-xs text-slate-400">{statusLabel[status]}</span>
234	          </div>
235	
236	          <div className="ml-auto flex items-center gap-2">
237	            <select
238	              value={serverId}
239	              onChange={(e) => setServerId(e.target.value)}
240	              disabled={live}
241	              className="max-w-[10rem] rounded-lg border border-white/10 bg-white/5 px-2.5 py-1.5 text-xs text-white outline-none focus:border-brand-400/60 disabled:opacity-50"
242	            >
243	              {servers.length === 0 && <option value="">No running servers</option>}
244	              {servers.map((s) => (
245	                <option key={s.id} value={s.id} className="bg-navy-900">
246	                  {s.hostname}
247	                </option>
248	              ))}
249	            </select>
250	
251	            {live ? (
252	              <button
253	                onClick={disconnect}
254	                className="rounded-lg border border-white/10 bg-white/5 px-3 py-1.5 text-xs font-semibold text-slate-200 hover:bg-white/10"
255	              >
256	                Disconnect
257	              </button>
258	            ) : (
259	              <button
260	                onClick={connect}
261	                disabled={!serverId}
262	                className="rounded-lg bg-brand-500 px-3 py-1.5 text-xs font-semibold text-white hover:bg-brand-400 disabled:opacity-50"
263	              >
264	                Connect
265	              </button>
266	            )}
267	
268	            <button
269	              onClick={onClose}
270	              className="rounded-lg p-1.5 text-slate-400 hover:bg-white/10 hover:text-white"
271	              aria-label="Close terminal"
272	            >
273	              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
274	                <path d="M18 6 6 18M6 6l12 12" />
275	              </svg>
276	            </button>
277	          </div>
278	        </div>
279	
280	        {/* Error banner */}
281	        {error && (
282	          <div className="flex-none border-b border-red-500/20 bg-red-500/10 px-4 py-2 text-xs text-red-200">
283	            {error}
284	          </div>
285	        )}
286	
287	        {/* Hint before first connect */}
288	        {status === "idle" && (
289	          <div className="flex-none border-b border-white/[0.06] bg-white/[0.02] px-4 py-2 text-xs text-slate-400">
290	            {selected
291	              ? <>Opens a root shell on <span className="font-semibold text-slate-200">{selected.hostname}</span>. Run <code className="rounded bg-white/10 px-1 text-slate-200">claude</code> to start building.</>
292	              : "Pick a running server, then press Connect."}
293	          </div>
294	        )}
295	
296	        {/* Terminal surface */}
297	        <div className="min-h-0 flex-1 bg-[#0a0e1a] p-2">
298	          <div ref={hostRef} className="h-full w-full" />
299	        </div>
300	      </div>
301	    </div>,
302	    document.body
303	  );
304	}
