1	"use client";
2	
3	import { useEffect, useMemo, useState } from "react";
4	import { createPortal } from "react-dom";
5	import { PageHeader } from "@/components/ui/primitives";
6	import { BuildConsole, type ServerOption } from "./BuildConsole";
7	import { PipelineBoard, type BoardBuild } from "./PipelineBoard";
8	import { listConsoleBuilds } from "@/lib/actions-claude-console";
9	import { mirrorFanout, MAX_CONSOLES, MIRROR_MIN, MIRROR_MAX } from "@/lib/claude-console-core";
10	
11	/**
12	 * Build Studio — the multi-console AI build workspace.
13	 *
14	 * The name is intentionally isolated in one constant: rename the product by
15	 * editing WORKSPACE_NAME (and the page metadata) — nothing else depends on it.
16	 */
17	export const WORKSPACE_NAME = "Build Studio";
18	
19	type ConsoleDescriptor = {
20	  id: string;
21	  serverId: string;
22	  autoPrompt?: string;
23	  mirrorLabel?: string | null;
24	  mirrorGroupId?: string | null;
25	  buildTitle?: string | null;
26	};
27	
28	let counter = 0;
29	const newId = () => `c${Date.now()}_${counter++}`;
30	
31	function gridColsFor(n: number): string {
32	  if (n <= 1) return "grid-cols-1";
33	  if (n === 2) return "grid-cols-1 lg:grid-cols-2";
34	  if (n <= 4) return "grid-cols-1 md:grid-cols-2";
35	  return "grid-cols-1 md:grid-cols-2 2xl:grid-cols-3";
36	}
37	
38	/* -------------------------------------------------------------------------- */
39	/* Mirror modal                                                                */
40	/* -------------------------------------------------------------------------- */
41	
42	function MirrorModal({
43	  servers,
44	  onClose,
45	  onLaunch,
46	}: {
47	  servers: ServerOption[];
48	  onClose: () => void;
49	  onLaunch: (prompt: string, serverIds: string[]) => void;
50	}) {
51	  const [prompt, setPrompt] = useState("");
52	  const [count, setCount] = useState(Math.min(2, MIRROR_MAX));
53	  const [targets, setTargets] = useState<string[]>(
54	    Array.from({ length: MIRROR_MAX }, () => servers[0]?.id ?? "")
55	  );
56	  const [error, setError] = useState<string | null>(null);
57	
58	  const slots = Array.from({ length: count }, (_, i) => i);
59	
60	  const launch = () => {
61	    setError(null);
62	    const serverIds = slots.map((i) => targets[i] || servers[0]?.id || "");
63	    try {
64	      // Validate the fan-out with the same pure logic the tests cover.
65	      mirrorFanout(prompt, serverIds, "preview");
66	    } catch (e) {
67	      setError(e instanceof Error ? e.message : "Invalid mirror configuration.");
68	      return;
69	    }
70	    onLaunch(prompt.trim(), serverIds);
71	  };
72	
73	  return createPortal(
74	    <div className="fixed inset-0 z-[60] flex items-start justify-center overflow-y-auto bg-black/70 p-4 backdrop-blur-sm sm:p-8" onClick={onClose}>
75	      <div className="my-auto w-full max-w-xl overflow-hidden rounded-2xl border border-white/10 bg-navy-900 shadow-2xl" onClick={(e) => e.stopPropagation()}>
76	        <div className="flex items-start justify-between gap-4 border-b border-white/[0.06] p-5">
77	          <div>
78	            <h3 className="text-base font-bold text-white">Mirror build</h3>
79	            <p className="mt-0.5 text-sm text-slate-400">
80	              Send the same task to {MIRROR_MIN}–{MIRROR_MAX} consoles at once — build it in parallel to compare variations. Each console stays independent and still needs its own approval.
81	            </p>
82	          </div>
83	          <button onClick={onClose} className="rounded-lg p-1.5 text-slate-400 hover:bg-white/10 hover:text-white" aria-label="Close">
84	            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
85	              <path d="M18 6 6 18M6 6l12 12" />
86	            </svg>
87	          </button>
88	        </div>
89	
90	        <div className="space-y-5 p-5">
91	          <div>
92	            <label className="mb-1.5 block text-xs font-semibold uppercase tracking-wider text-slate-500">Shared prompt</label>
93	            <textarea
94	              value={prompt}
95	              onChange={(e) => setPrompt(e.target.value)}
96	              placeholder="e.g. Build a modern landing page for a coffee shop with a menu and a contact form."
97	              rows={3}
98	              maxLength={2000}
99	              className="w-full resize-y rounded-xl border border-white/10 bg-white/5 px-3 py-2 text-sm text-white outline-none placeholder:text-slate-600 focus:border-brand-400/60"
100	            />
101	          </div>
102	
103	          <div>
104	            <label className="mb-1.5 block text-xs font-semibold uppercase tracking-wider text-slate-500">How many consoles</label>
105	            <div className="flex flex-wrap gap-1.5">
106	              {Array.from({ length: MIRROR_MAX - MIRROR_MIN + 1 }, (_, i) => MIRROR_MIN + i).map((n) => (
107	                <button
108	                  key={n}
109	                  type="button"
110	                  onClick={() => setCount(n)}
111	                  className={`h-9 w-9 rounded-lg text-sm font-semibold transition ${count === n ? "bg-brand-500 text-white" : "border border-white/10 bg-white/5 text-slate-300 hover:bg-white/10"}`}
112	                >
113	                  {n}
114	                </button>
115	              ))}
116	            </div>
117	          </div>
118	
119	          <div>
120	            <label className="mb-1.5 block text-xs font-semibold uppercase tracking-wider text-slate-500">Target server per console</label>
121	            <div className="grid gap-2 sm:grid-cols-2">
122	              {slots.map((i) => (
123	                <label key={i} className="flex items-center gap-2 rounded-lg border border-white/10 bg-white/5 px-2.5 py-1.5">
124	                  <span className="flex h-6 w-6 flex-none items-center justify-center rounded-md bg-brand-500/20 text-[11px] font-bold text-brand-200">
125	                    {String.fromCharCode(65 + i)}
126	                  </span>
127	                  <select
128	                    value={targets[i] ?? ""}
129	                    onChange={(e) => setTargets((prev) => prev.map((v, j) => (j === i ? e.target.value : v)))}
130	                    className="min-w-0 flex-1 bg-transparent text-xs text-white outline-none"
131	                  >
132	                    {servers.map((s) => (
133	                      <option key={s.id} value={s.id} className="bg-navy-900">
134	                        {s.hostname}
135	                      </option>
136	                    ))}
137	                  </select>
138	                </label>
139	              ))}
140	            </div>
141	            <p className="mt-1.5 text-[11px] text-slate-500">
142	              Tip: point them at the same server to try variations in place, or at different servers to build in parallel.
143	            </p>
144	          </div>
145	
146	          {error && <p className="text-sm text-red-300">{error}</p>}
147	
148	          <div className="flex items-center gap-3">
149	            <button type="button" onClick={launch} disabled={prompt.trim().length < 8} className="btn-primary disabled:cursor-not-allowed disabled:opacity-50">
150	              Launch {count} consoles
151	            </button>
152	            <button type="button" onClick={onClose} className="btn-secondary">
153	              Cancel
154	            </button>
155	          </div>
156	        </div>
157	      </div>
158	    </div>,
159	    document.body
160	  );
161	}
162	
163	/* -------------------------------------------------------------------------- */
164	/* Workspace                                                                    */
165	/* -------------------------------------------------------------------------- */
166	
167	export function BuildStudio({
168	  servers,
169	  recentBuilds,
170	}: {
171	  servers: ServerOption[];
172	  recentBuilds: BoardBuild[];
173	}) {
174	  const [consoles, setConsoles] = useState<ConsoleDescriptor[]>(() =>
175	    servers[0] ? [{ id: newId(), serverId: servers[0].id }] : []
176	  );
177	  const [mirrorOpen, setMirrorOpen] = useState(false);
178	  const [showBoard, setShowBoard] = useState(false);
179	  const [board, setBoard] = useState<BoardBuild[]>(recentBuilds);
180	
181	  // While the pipeline is open, refresh it from the server (ownership-checked)
182	  // so cards track real status as consoles progress. Polls only while visible.
183	  useEffect(() => {
184	    if (!showBoard) return;
185	    let alive = true;
186	    const refresh = async () => {
187	      try {
188	        const rows = await listConsoleBuilds(24);
189	        if (alive) setBoard(rows);
190	      } catch {
191	        /* keep the last snapshot */
192	      }
193	    };
194	    void refresh();
195	    const timer = setInterval(refresh, 4000);
196	    return () => {
197	      alive = false;
198	      clearInterval(timer);
199	    };
200	  }, [showBoard]);
201	
202	  const atMax = consoles.length >= MAX_CONSOLES;
203	
204	  const addConsole = () => {
205	    if (atMax) return;
206	    setConsoles((prev) => [...prev, { id: newId(), serverId: servers[0]?.id ?? "" }]);
207	  };
208	
209	  const removeConsole = (id: string) => setConsoles((prev) => prev.filter((c) => c.id !== id));
210	
211	  const launchMirror = (prompt: string, serverIds: string[]) => {
212	    const groupId = `mir_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 6)}`;
213	    // Pure fan-out (unit-tested) produces one descriptor per console.
214	    const reqs = mirrorFanout(prompt, serverIds, groupId);
215	    const built: ConsoleDescriptor[] = reqs.map((r, i) => ({
216	      id: newId(),
217	      serverId: r.serverId,
218	      autoPrompt: r.prompt,
219	      mirrorLabel: `Mirror ${String.fromCharCode(65 + i)}`,
220	      mirrorGroupId: r.mirrorGroupId,
221	      buildTitle: r.title,
222	    }));
223	    // Mirror replaces the current console set so all N are visible together.
224	    setConsoles(built);
225	    setMirrorOpen(false);
226	  };
227	
228	  const dense = consoles.length > 2;
229	  const cols = useMemo(() => gridColsFor(consoles.length), [consoles.length]);
230	
231	  return (
232	    <div className="space-y-5">
233	      <div className="flex flex-wrap items-start justify-between gap-3">
234	        <PageHeader
235	          title={WORKSPACE_NAME}
236	          sub={`Open up to ${MAX_CONSOLES} AI build consoles at once — each an independent chat that plans, you approve, then it configures a server you own. BYOK; nothing runs until you approve.`}
237	        />
238	        <div className="flex flex-wrap items-center gap-2">
239	          <button
240	            type="button"
241	            onClick={() => setShowBoard((v) => !v)}
242	            className="rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm font-semibold text-slate-200 hover:bg-white/10"
243	          >
244	            {showBoard ? "Hide" : "Pipeline"}
245	          </button>
246	          <button
247	            type="button"
248	            onClick={() => setMirrorOpen(true)}
249	            disabled={servers.length === 0}
250	            className="inline-flex items-center gap-1.5 rounded-lg border border-brand-400/30 bg-brand-500/10 px-3 py-2 text-sm font-semibold text-brand-200 hover:bg-brand-500/20 disabled:cursor-not-allowed disabled:opacity-50"
251	            title="Send one prompt to several consoles at once"
252	          >
253	            <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
254	              <rect x="3" y="4" width="7" height="16" rx="1.5" />
255	              <rect x="14" y="4" width="7" height="16" rx="1.5" />
256	            </svg>
257	            Mirror build
258	          </button>
259	          <button
260	            type="button"
261	            onClick={addConsole}
262	            disabled={atMax || servers.length === 0}
263	            className="btn-primary disabled:cursor-not-allowed disabled:opacity-50"
264	            title={atMax ? `Maximum ${MAX_CONSOLES} consoles` : "Open another console"}
265	          >
266	            + Console
267	          </button>
268	        </div>
269	      </div>
270	
271	      {showBoard && <PipelineBoard builds={board} />}
272	
273	      {consoles.length === 0 ? (
274	        <div className="card p-8 text-center">
