276	          <button type="button" onClick={addConsole} disabled={servers.length === 0} className="btn-primary mt-4 disabled:opacity-50">
277	            Open a console
278	          </button>
279	        </div>
280	      ) : (
281	        <div className={`grid gap-4 ${cols}`}>
282	          {consoles.map((c, i) => (
283	            <div key={c.id} className={consoles.length === 1 ? "h-[560px]" : "h-[480px]"}>
284	              <BuildConsole
285	                consoleId={c.id}
286	                index={i}
287	                servers={servers}
288	                initialServerId={c.serverId}
289	                autoPrompt={c.autoPrompt}
290	                mirrorLabel={c.mirrorLabel}
291	                mirrorGroupId={c.mirrorGroupId}
292	                buildTitle={c.buildTitle}
293	                canRemove={consoles.length > 1}
294	                onRemove={() => removeConsole(c.id)}
295	                dense={dense}
296	              />
297	            </div>
298	          ))}
299	        </div>
300	      )}
301	
302	      {mirrorOpen && <MirrorModal servers={servers} onClose={() => setMirrorOpen(false)} onLaunch={launchMirror} />}
303	    </div>
304	  );
305	}
