45	/* -------------------------------------------------------------------------- */
46	/* Web Speech API (voice-to-text) — typed minimally, degrades gracefully.      */
47	/* -------------------------------------------------------------------------- */
48	
49	type SpeechRecognitionLike = {
50	  lang: string;
51	  continuous: boolean;
52	  interimResults: boolean;
53	  start: () => void;
54	  stop: () => void;
55	  onresult: ((e: { results: ArrayLike<ArrayLike<{ transcript: string }>> }) => void) | null;
56	  onerror: (() => void) | null;
57	  onend: (() => void) | null;
58	};
59	
60	function getSpeechRecognitionCtor(): (new () => SpeechRecognitionLike) | null {
61	  if (typeof window === "undefined") return null;
62	  const w = window as unknown as {
63	    SpeechRecognition?: new () => SpeechRecognitionLike;
64	    webkitSpeechRecognition?: new () => SpeechRecognitionLike;
65	  };
66	  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
67	}
68	
69	/* -------------------------------------------------------------------------- */
70	/* Helpers                                                                     */
71	/* -------------------------------------------------------------------------- */
72	
73	function parsePlan(raw: string | null): PlanStep[] {
74	  if (!raw) return [];
75	  try {
76	    const p = JSON.parse(raw);
77	    if (Array.isArray(p)) {
78	      return p
79	        .map((s) => (typeof s === "string" ? { cmd: s } : { cmd: String(s?.cmd ?? ""), intent: s?.intent }))
80	        .filter((s) => s.cmd);
81	    }
82	  } catch {
83	    /* ignore */
84	  }
85	  return [];
86	}
