152	      const clean = promptText.trim();
153	      if (clean.length < 8 || !serverId || pending) return;
154	      setPending(true);
155	      const key = nextKey();
156	      setTurns((prev) => [
157	        ...prev,
158	        { key, prompt: clean, images: imgs, buildId: null, status: "PLANNING", steps: 0, log: "", plan: null, error: null },
159	      ]);
160	      setInput("");
161	      setImages([]);
162	
163	      const res = await planConsoleBuild(serverId, clean, imgs, mirrorGroupId, buildTitle).catch((e) => ({
164	        error: e instanceof Error ? e.message : "Planning failed.",
165	      }));
166	      setTurns((prev) =>
167	        prev.map((t) =>
168	          t.key === key
169	            ? "error" in res && res.error
170	              ? { ...t, status: "FAILED", error: res.error }
171	              : { ...t, buildId: (res as { buildId?: string }).buildId ?? null, status: "AWAITING_APPROVAL" }
