206	    else if (src[i] === ")" && --parens === 0) break;
207	  }
208	  let angles = 0;
209	  for (i++; i < src.length; i++) {
210	    if (src[i] === "<") angles++;
211	    else if (src[i] === ">") angles = Math.max(0, angles - 1);
212	    else if (src[i] === "{" && angles === 0) break;
213	  }
214	  const start = i;
215	  let depth = 0;
216	  for (; i < src.length; i++) {
217	    if (src[i] === "{") depth++;
218	    else if (src[i] === "}" && --depth === 0) return src.slice(start, i + 1);
219	  }
