17	 * Portal-wide, PERSISTENT terminal dock.
18	 *
19	 * The whole point of this component is that it is mounted ONCE, at the portal
20	 * shell level (components/portal/Shell.tsx). Because the App Router keeps Shell
21	 * mounted across in-portal navigation, the dock — and every live shell session
22	 * it holds — survives page changes. Navigating from /dashboard/servers/x to
23	 * /dashboard/build never unmounts the websocket, so a running `claude` build
24	 * keeps going.
25	 *
26	 * How sessions survive re-renders / route changes / minimize↔restore:
27	 *   - The tab bar is driven by `sessions` state (plain metadata: id, hostname,
28	 *     status) so the UI re-renders normally.
29	 *   - The LIVE objects for each session — the xterm `Terminal`, its `FitAddon`,
30	 *     the `WebSocket`, the `ResizeObserver`, and a PERSISTENT container <div> —
31	 *     live in a `Map` ref (`liveRef`). Refs are never recreated by React, so
32	 *     these objects (and the socket) outlive every render.
33	 *   - Each session's xterm is attached to its own persistent container div
34	 *     (created once, stored in the ref). The dock renders one mount slot per
35	 *     session and appends that same div into it via a ref callback. Switching
36	 *     the active tab just toggles `display`; the hidden sessions keep their
37	 *     sockets open in the background. Toggling maximize↔minimize only changes
38	 *     the OUTER wrapper's size/position classes — the surface holding the
39	 *     containers keeps the same DOM nodes, so xterm/scrollback/socket are never
40	 *     recreated.
41	 *
42	 * Wire protocol + connection logic are reused verbatim from the old
43	 * components/customer/WebTerminal.tsx (token → wss /terminal-ws → JSON
44	 * {type:"data"|"resize"} up, raw output down).
45	 */
46	
47	export type TerminalServerRef = { id: string; hostname: string };
48	
49	type Status = "connecting" | "connected" | "closed" | "error";
50	type Mode = "hidden" | "maximized" | "minimized";
51	
52	type SessionMeta = { id: string; hostname: string; status: Status };
53	
54	type LiveSession = {
55	  id: string;
56	  hostname: string;
57	  container: HTMLDivElement;
58	  term: XTerm | null;
59	  fit: XFitAddon | null;
60	  ws: WebSocket | null;
61	  ro: ResizeObserver | null;
62	  starting: boolean;
63	};
64	
65	type DockApi = {
66	  openSession: (server: TerminalServerRef) => void;
67	  focusSession: (id: string) => void;
68	  closeSession: (id: string) => void;
69	  minimize: () => void;
70	  restore: () => void;
71	  close: () => void;
72	};
73	
74	const DockContext = createContext<DockApi | null>(null);
75	
76	/** Hook exposing the dock controls to any client component inside Shell. */
77	export function useTerminalDock(): DockApi {
78	  const ctx = useContext(DockContext);
79	  if (!ctx) throw new Error("useTerminalDock must be used within <TerminalDockProvider>");
80	  return ctx;
81	}
82	
83	/* -------------------------------------------------------------------------- */
84	/* Provider — owns all state + the live-session ref map + the dock controls    */
85	/* -------------------------------------------------------------------------- */
86	
87	export function TerminalDockProvider({ children }: { children: React.ReactNode }) {
88	  const [sessions, setSessions] = useState<SessionMeta[]>([]);
89	  const [activeId, setActiveId] = useState<string | null>(null);
90	  const [mode, setMode] = useState<Mode>("hidden");
91	  const [errors, setErrors] = useState<Record<string, string>>({});
92	
93	  // Live xterm/ws/container objects, keyed by server id. Never recreated by
94	  // React — this is what makes sessions survive navigation and re-renders.
95	  const liveRef = useRef<Map<string, LiveSession>>(new Map());
96	
97	  const setStatus = useCallback((id: string, status: Status) => {
98	    setSessions((prev) => prev.map((s) => (s.id === id ? { ...s, status } : s)));
99	  }, []);
100	
101	  const fitAndResize = useCallback((id: string) => {
102	    const live = liveRef.current.get(id);
103	    if (!live || !live.term || !live.fit) return;
104	    try {
105	      live.fit.fit();
106	    } catch {
107	      /* ignore */
108	    }
109	    const ws = live.ws;
110	    if (ws && ws.readyState === WebSocket.OPEN) {
111	      ws.send(JSON.stringify({ type: "resize", cols: live.term.cols, rows: live.term.rows }));
112	    }
113	  }, []);
114	
115	  /** Build the xterm + websocket for a session whose container is in the DOM. */
116	  const connect = useCallback(
117	    async (id: string) => {
118	      const live = liveRef.current.get(id);
119	      if (!live || live.starting || live.term) return;
120	      live.starting = true;
121	      setStatus(id, "connecting");
122	      setErrors((e) => {
123	        if (!e[id]) return e;
124	        const next = { ...e };
125	        delete next[id];
126	        return next;
127	      });
128	
129	      // 1. Mint a short-lived token (session + ownership checked server-side).
130	      let token: string;
131	      try {
132	        const res = await fetch("/api/terminal/token", {
133	          method: "POST",
134	          headers: { "Content-Type": "application/json" },
135	          body: JSON.stringify({ serverId: id }),
136	        });
137	        const body = await res.json().catch(() => ({}));
138	        if (!res.ok) throw new Error(body?.error || "Could not authorize the terminal.");
139	        token = body.token;
140	        if (!token) throw new Error("No terminal token was issued.");
141	      } catch (e) {
142	        live.starting = false;
143	        setStatus(id, "error");
144	        setErrors((prev) => ({
145	          ...prev,
146	          [id]: e instanceof Error ? e.message : "Could not authorize the terminal.",
147	        }));
148	        return;
149	      }
150	      if (!liveRef.current.has(id)) return; // closed while awaiting
151	
152	      // 2. Build the terminal into the session's persistent container.
153	      const [{ Terminal }, { FitAddon }] = await Promise.all([
154	        import("@xterm/xterm"),
155	        import("@xterm/addon-fit"),
156	      ]);
157	      if (!liveRef.current.has(id)) return;
158	
159	      const term = new Terminal({
160	        cursorBlink: true,
161	        fontFamily:
162	          'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace',
163	        fontSize: 13,
164	        theme: { background: "#0a0e1a", foreground: "#e2e8f0", cursor: "#e2e8f0" },
165	      });
166	      const fit = new FitAddon();
167	      term.loadAddon(fit);
168	      term.open(live.container);
169	      try {
170	        fit.fit();
171	      } catch {
172	        /* ignore */
173	      }
174	      live.term = term;
175	      live.fit = fit;
176	
177	      // 3. Open the websocket to the PTY backend (nginx proxies /terminal-ws).
178	      const scheme = location.protocol === "https:" ? "wss" : "ws";
179	      const ws = new WebSocket(
180	        `${scheme}://${location.host}/terminal-ws?token=${encodeURIComponent(token)}`
181	      );
182	      ws.binaryType = "arraybuffer";
183	      live.ws = ws;
184	
185	      ws.onopen = () => {
186	        setStatus(id, "connected");
187	        term.focus();
188	        fitAndResize(id);
189	      };
190	      ws.onmessage = (ev) => {
191	        if (typeof ev.data === "string") {
192	          term.write(ev.data);
193	        } else if (ev.data instanceof ArrayBuffer) {
194	          term.write(new Uint8Array(ev.data));
195	        }
196	      };
197	      ws.onerror = () => {
198	        setErrors((prev) => ({ ...prev, [id]: "Connection error." }));
199	      };
200	      ws.onclose = (ev) => {
201	        setStatus(id, "closed");
202	        if (ev.reason && live.term) {
203	          term.write(`\r\n\x1b[90m[${ev.reason}]\x1b[0m\r\n`);
204	        }
205	      };
206	
207	      // 4. Keystrokes → server.
208	      term.onData((data) => {
209	        if (ws.readyState === WebSocket.OPEN) {
210	          ws.send(JSON.stringify({ type: "data", data }));
211	        }
212	      });
213	
214	      // 5. Keep the PTY window sized to the visible surface.
215	      const ro = new ResizeObserver(() => fitAndResize(id));
216	      ro.observe(live.container);
217	      live.ro = ro;
218	    },
219	    [fitAndResize, setStatus]
220	  );
221	
222	  /** Tear down a session's live socket + xterm (idempotent). */
223	  const teardownLive = useCallback((live: LiveSession) => {
224	    try {
225	      live.ro?.disconnect();
226	    } catch {
227	      /* ignore */
228	    }
229	    live.ro = null;
230	    try {
231	      live.ws?.close();
232	    } catch {
233	      /* ignore */
234	    }
235	    live.ws = null;
236	    try {
237	      live.term?.dispose();
238	    } catch {
239	      /* ignore */
240	    }
241	    live.term = null;
242	    live.fit = null;
243	    try {
244	      live.container.remove();
245	    } catch {
246	      /* ignore */
247	    }
248	  }, []);
249	
250	  /* ------------------------------- controls ------------------------------- */
251	
252	  const openSession = useCallback((server: TerminalServerRef) => {
253	    const map = liveRef.current;
254	    if (map.has(server.id)) {
255	      // Already a tab — focus it instead of duplicating.
256	      setActiveId(server.id);
257	      setMode("maximized");
258	      return;
259	    }
260	    const container = document.createElement("div");
261	    container.className = "h-full w-full";
262	    map.set(server.id, {
263	      id: server.id,
264	      hostname: server.hostname,
265	      container,
266	      term: null,
267	      fit: null,
268	      ws: null,
269	      ro: null,
270	      starting: false,
271	    });
272	    setSessions((prev) => [...prev, { id: server.id, hostname: server.hostname, status: "connecting" }]);
273	    setActiveId(server.id);
274	    setMode("maximized");
275	  }, []);
276	
277	  const focusSession = useCallback((id: string) => {
278	    setActiveId(id);
279	    setMode((m) => (m === "minimized" ? "minimized" : "maximized"));
280	  }, []);
281	
282	  const closeSession = useCallback(
283	    (id: string) => {
284	      const live = liveRef.current.get(id);
285	      if (live) teardownLive(live);
286	      liveRef.current.delete(id);
287	      setErrors((prev) => {
288	        if (!prev[id]) return prev;
289	        const next = { ...prev };
290	        delete next[id];
291	        return next;
292	      });
293	      setSessions((prev) => {
294	        const next = prev.filter((s) => s.id !== id);
295	        if (next.length === 0) {
296	          setMode("hidden");
297	          setActiveId(null);
298	        } else {
299	          setActiveId((a) => (a === id ? next[0].id : a));
300	        }
301	        return next;
302	      });
303	    },
304	    [teardownLive]
305	  );
306	
307	  const minimize = useCallback(() => setMode("minimized"), []);
308	  const restore = useCallback(() => setMode("maximized"), []);
309	
310	  const close = useCallback(() => {
311	    for (const live of liveRef.current.values()) teardownLive(live);
312	    liveRef.current.clear();
313	    setSessions([]);
314	    setActiveId(null);
315	    setErrors({});
316	    setMode("hidden");
317	  }, [teardownLive]);
318	
319	  /** Reconnect a session in place (keeps its tab + persistent container). */
320	  const reconnect = useCallback(
321	    (id: string) => {
322	      const live = liveRef.current.get(id);
323	      if (!live) return;
324	      try {
325	        live.ro?.disconnect();
326	      } catch {
327	        /* ignore */
328	      }
329	      live.ro = null;
330	      try {
331	        live.ws?.close();
332	      } catch {
333	        /* ignore */
334	      }
335	      live.ws = null;
336	      try {
337	        live.term?.dispose();
338	      } catch {
339	        /* ignore */
340	      }
341	      live.term = null;
342	      live.fit = null;
343	      live.starting = false;
344	      live.container.innerHTML = "";
345	      void connect(id);
346	    },
347	    [connect]
348	  );
349	
350	  /** Mount slot: append the session's persistent container, kick off connect. */
351	  const attach = useCallback(
352	    (id: string, el: HTMLDivElement | null) => {
353	      const live = liveRef.current.get(id);
354	      if (!live || !el) return; // on unmount (el === null) we keep the container alive
355	      if (live.container.parentElement !== el) {
356	        el.appendChild(live.container);
357	      }
358	      if (!live.term && !live.starting) void connect(id);
359	    },
360	    [connect]
361	  );
362	
363	  // Refit the active session whenever it becomes visible or the dock resizes.
364	  useEffect(() => {
365	    if (!activeId || mode === "hidden") return;
366	    const raf = requestAnimationFrame(() => fitAndResize(activeId));
367	    return () => cancelAnimationFrame(raf);
368	  }, [activeId, mode, fitAndResize]);
369	
370	  const api: DockApi = {
371	    openSession,
372	    focusSession,
373	    closeSession,
374	    minimize,
375	    restore,
376	    close,
377	  };
378	
379	  return (
380	    <DockContext.Provider value={api}>
381	      {children}
382	      <TerminalDock
383	        sessions={sessions}
384	        activeId={activeId}
385	        mode={mode}
386	        errors={errors}
387	        attach={attach}
388	        focusSession={focusSession}
389	        closeSession={closeSession}
390	        openSession={openSession}
391	        minimize={minimize}
392	        restore={restore}
393	        close={close}
394	        reconnect={reconnect}
395	      />
396	    </DockContext.Provider>
397	  );
398	}
