          sub="Open several AI build consoles at once — build with your Anthropic key, or with Claude running on your own server."
        />
        <EmptyState
          title="No running servers"
          sub="Matrix builds on a running server. Start or deploy one, then come back here."
          action={
            <Link href="/dashboard/servers" className="btn-primary">
              Go to servers
            </Link>
          }
        />
      </div>
    );
  }

  return <BuildStudio servers={servers} recentBuilds={recentBuilds} keyConnected={keyConnected} />;
}

